import { AppShell } from "@/layout/AppShell"

// AppShell's `navigation` prop (see ./layout/navItems.ts's `NavItem`)
// drives both the desktop Sidebar rail and the mobile BottomNav. Left empty
// here so a fresh app never ships dead links; BottomNav renders nothing (not
// an empty bar) for an empty list. Replace with your own items once real
// in-app destinations exist, e.g. [{ label: "Home", icon: House, href: "/",
// active: true }] with House from lucide-react. To link out to Finnomena's
// own ecosystem instead, import `finnomenaEcosystemNav` from
// "@/layout/navItems" and pass it here.
export function App() {
  return (
    <AppShell
      sidebar={null}
      navigation={[]}
      content={<div>Content</div>}
      inspector={<div>Inspector — start building here</div>}
    />
  )
}

// The app's one provider root. theme.css reads data-theme on <html>, so the
// color scheme is a single attribute; no theme provider is needed. The root
// also holds the one TooltipProvider and Toaster, so screens add neither.
import { useLayoutEffect, type ReactNode } from "react"
import { Toaster } from "@/components/ui/sonner"
import { TooltipProvider } from "@/components/ui/tooltip"
import { ColorSchemeContext, type ColorScheme } from "./colorScheme"

export function AppRoot({ children, colorScheme = "light" }: { children: ReactNode; colorScheme?: ColorScheme }) {
  useLayoutEffect(() => {
    const root = document.documentElement
    root.dataset.theme = colorScheme
    root.style.colorScheme = colorScheme
  }, [colorScheme])
  return (
    <ColorSchemeContext.Provider value={colorScheme}>
      <TooltipProvider>
        {children}
        <Toaster theme={colorScheme} />
      </TooltipProvider>
    </ColorSchemeContext.Provider>
  )
}

import { createContext, useContext } from "react"

export type ColorScheme = "light" | "dark"
export const ColorSchemeContext = createContext<ColorScheme>("light")
/** The active color scheme, for the rare component that must branch on it. */
export const useColorScheme = () => useContext(ColorSchemeContext)
